import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Family visas","description":"How residents bring a spouse and children to live in Qatar, host relatives on a family visit, and bring in a newborn.","frontmatter":{"title":"Family visas","description":"How residents bring a spouse and children to live in Qatar, host relatives on a family visit, and bring in a newborn.","lastChecked":"2026-10","sourceCount":7},"headers":[],"relativePath":"guide/family-visas.md","filePath":"guide/family-visas.md"}'),i={name:"guide/family-visas.md"};function n(s,e,f,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="family-visas" tabindex="-1">Family visas <a class="header-anchor" href="#family-visas" aria-label="Permalink to &quot;Family visas&quot;">​</a></h1><p>If you hold a valid residence permit for work in Qatar, you can apply to bring your wife and children to live with you, or host relatives on a family visit. Both applications are made on the Metrash2 app.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><p>The Ministry of Interior (MOI) changed the rules in an announcement dated 05/12/2023. Salary and housing conditions now depend on what your electronic work contract says.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="family-residence-for-your-spouse-and-children" tabindex="-1">Family residence for your spouse and children <a class="header-anchor" href="#family-residence-for-your-spouse-and-children" aria-label="Permalink to &quot;Family residence for your spouse and children&quot;">​</a></h2><h3 id="who-can-apply" tabindex="-1">Who can apply <a class="header-anchor" href="#who-can-apply" aria-label="Permalink to &quot;Who can apply&quot;">​</a></h3><ul><li>You need a valid residence permit for work.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></li><li>Government and semi-government employees need a senior profession, shown in the employment contract or an official letter from the employer. They also need family housing from the employer or a monthly salary of at least QAR 10,000 as stated in the contract.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>Private sector employees need a technical or specialized (non-labour) profession shown in the contract. They also need a salary of at least QAR 10,000, or QR 6,000 with family housing provided by the employer and shown in the contract.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>An older MOI conditions page still gives QR 7,000 for the housing option. The 2023 announcement and the service page both say 6,000.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup><sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li></ul><h3 id="who-you-can-bring" tabindex="-1">Who you can bring <a class="header-anchor" href="#who-you-can-bring" aria-label="Permalink to &quot;Who you can bring&quot;">​</a></h3><ul><li>MOI&#39;s service page covers wives and children coming for the first time on a residence visa.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>A son must be no older than 25 and a daughter must be unmarried.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li></ul><h3 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h3><ul><li>A valid passport copy of the expatriate host.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>A document that proves the relationship.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>A Good Conduct Certificate (Police Clearance Certificate) for family members aged 18 and above.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>Health insurance that covers the stay and starts from the date of entry.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li></ul><h3 id="school-age-children" tabindex="-1">School-age children <a class="header-anchor" href="#school-age-children" aria-label="Permalink to &quot;School-age children&quot;">​</a></h3><p>Children aged 6 to 18 must be registered at a licensed school in Qatar, or you must attach proof that they are enrolled in education abroad, through the education platform run by the education ministry. MOI says this is required both when the residence permit is granted and when it is renewed.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></p><h3 id="how-to-apply" tabindex="-1">How to apply <a class="header-anchor" href="#how-to-apply" aria-label="Permalink to &quot;How to apply&quot;">​</a></h3><ol><li>Submit the application on Metrash2 and upload the documents.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li>After your family arrives on a residence visa, they complete the medical checkup within thirty days, then fingerprints and the residency procedures.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ol><p>The next steps are on the <a href="./residence-permit-and-qid">Residence permit and QID</a> page.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></p><h2 id="family-visit-visa" tabindex="-1">Family visit visa <a class="header-anchor" href="#family-visit-visa" aria-label="Permalink to &quot;Family visit visa&quot;">​</a></h2><p>MOI grants this visa for one month, and it can be extended for another five months for first degree relatives.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><h3 id="who-can-host" tabindex="-1">Who can host <a class="header-anchor" href="#who-can-host" aria-label="Permalink to &quot;Who can host&quot;">​</a></h3><ul><li>Your profession must not be in the labour category.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>You need a monthly salary of at least QAR 5,000 shown in an accredited employment contract.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup><sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></li><li>The visitor needs health insurance for the period of the visit.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li></ul><h3 id="who-can-visit" tabindex="-1">Who can visit <a class="header-anchor" href="#who-can-visit" aria-label="Permalink to &quot;Who can visit&quot;">​</a></h3><ul><li>First degree: father, mother, wife, children.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li>Second degree: brother, sister, grandfather, grandmother, grandchildren.<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2]</a></sup></li><li>Third degree: children of a brother or sister, and uncles and aunts on both sides.<sup class="footnote-ref"><a href="#fn2" id="fnref2:7">[2]</a></sup></li></ul><p>The 2023 announcement says the visitor&#39;s age is not limited.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></p><h3 id="what-you-need-1" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need-1" aria-label="Permalink to &quot;What you need&quot;">​</a></h3><ul><li>A copy of the visitor&#39;s passport, valid for at least six months.<sup class="footnote-ref"><a href="#fn2" id="fnref2:8">[2]</a></sup></li><li>A document that proves the relationship.<sup class="footnote-ref"><a href="#fn2" id="fnref2:9">[2]</a></sup></li><li>Proof of family accommodation in the host&#39;s name, accredited by the relevant authorities.<sup class="footnote-ref"><a href="#fn2" id="fnref2:10">[2]</a></sup></li></ul><h3 id="how-to-apply-1" tabindex="-1">How to apply <a class="header-anchor" href="#how-to-apply-1" aria-label="Permalink to &quot;How to apply&quot;">​</a></h3><p>Submit the application on Metrash2 and upload the documents.<sup class="footnote-ref"><a href="#fn2" id="fnref2:11">[2]</a></sup></p><h2 id="staying-longer-on-a-family-visit" tabindex="-1">Staying longer on a family visit <a class="header-anchor" href="#staying-longer-on-a-family-visit" aria-label="Permalink to &quot;Staying longer on a family visit&quot;">​</a></h2><ul><li>To stay more than one month, finish the medical checkup before the allowed period ends and apply for the extension.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>MOI&#39;s Visa Services page has a Visa Extension / Fine Payment option.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>A visa that is not extended before it expires brings a fine for each day of delay. The amounts are on the MOI tips page.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li></ul><h2 id="newborn-babies" tabindex="-1">Newborn babies <a class="header-anchor" href="#newborn-babies" aria-label="Permalink to &quot;Newborn babies&quot;">​</a></h2><p>MOI has a free visa for babies arriving with their mother at the border, for use with their residence permit procedures. The baby must be not more than 6 months old.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><ul><li>Both parents&#39; residence permits must be valid, and the wife must be on her husband&#39;s sponsorship.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></li><li>Bring the original attested birth certificate and the baby&#39;s valid passport.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup></li><li>This is handled at the port of entry by Border Passports.<sup class="footnote-ref"><a href="#fn7" id="fnref7:3">[7]</a></sup></li></ul><p>See also: <a href="./arriving-and-visas">Arriving and visas</a>, <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./metrash">Metrash</a>, <a href="./education">Education</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bentry%2Ffamily%2Bresidence%2Bvisa" target="_blank" rel="noreferrer">Family Residence Visa</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bvisit%2Fgggg" target="_blank" rel="noreferrer">Family Visit</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:11" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-ar/sa-moinews/d978dff7-9fa3-4d39-a83f-cb3c3044dc52" target="_blank" rel="noreferrer">Announcement of changes to the rules for bringing residents&#39; families for residence or visit (in Arabic)</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/ganationalborderexpatriateaffairs/!ut/p/z0/fY5BC4JAEEZ_jUeZzUPgUSKKggwMqr3E5I4y5c7aOpT9-yQ6d_sefDweWDiBFXxyi8pBsJv4bOeXXW6KWV6abbnIl9Mstodyvc-qIoMKNmD_XyYH3x4PW4CtgyiNCqdX7Tu-pjxhFNKUJDEDpo56jOpJtA7esypRYloSitih8yw8aPy2hUZ-jazva4iO4oDiaOxRI6MSNg1yHBLjWoX-vjp-AE6OsDQ!/" target="_blank" rel="noreferrer">Conditions for Family Residence Visa Approval</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">Tips &amp; Guidelines</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/visaservices" target="_blank" rel="noreferrer">Visa Services</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bentry%2Fvisa0125" target="_blank" rel="noreferrer">Visa for New Born Babies</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:3" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',35)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
